// Where we got to last time. n8n keeps this per workflow, on the server, between runs -
// but only for an ACTIVE workflow. A manual test run always starts from 0.
const store = $getWorkflowStaticData('global');
const item = $input.first().json;
return [{ json: { ...item, since: Number(store.cursor ?? 0) } }];

// New events -> what to create in Jira, oldest first.
//   case.decided {answer:"yes", projectId, title}  -> an Epic, once per project (an idea that joins a
//                                                     project that already has its epic makes none)
//   project.step.added without payload.external     -> an issue under the project's epic
// A step with payload.external already lives in another tool, and a step of a project with no epic
// here (opened before this workflow was active) gets no issue: both are left alone.
const r = $input.first().json;
const s = $('Settings').first().json;
const store = $getWorkflowStaticData('global');
const projects = store.projects ?? {};
const steps = store.steps ?? {};

const events = Array.isArray(r.events) ? r.events : [];
const jobs = [];
const epics = new Set();
const issues = new Set();
let first = null; // seq of the first event that still needs Jira
for (const e of events) {
  const p = e.payload ?? {};
  let job = null;
  if (e.type === 'case.decided' && p.answer === 'yes' && typeof p.projectId === 'string') {
    if (projects[p.projectId] || epics.has(p.projectId)) continue;
    epics.add(p.projectId);
    job = { job: 'epic', projectId: p.projectId, title: String(p.title ?? '').trim() || 'NextUp project ' + p.projectId };
  } else if (e.type === 'project.step.added' && !p.external && typeof p.stepId === 'string' && typeof e.target === 'string') {
    if (steps[p.stepId] || issues.has(p.stepId)) continue;
    if (!projects[e.target] && !epics.has(e.target)) continue;
    issues.add(p.stepId);
    job = { job: 'issue', projectId: e.target, stepId: p.stepId, text: String(p.text ?? '').trim() || 'Step ' + p.stepId };
  }
  if (!job) continue;
  if (first === null) first = e.seq;
  jobs.push({ slug: s.slug, apiBase: s.apiBase, ...job });
}

// A run by hand (Execute workflow) reads from 0 and keeps no static data, so creating anything
// would make duplicates. It only shows what the active workflow would create.
if ($execution.mode !== 'production') return [{ json: { dryRun: true, wouldCreate: jobs } }];

// The cursor stops just before the first event with work, so a job that failed (Jira down, a wrong
// setting) is tried again next minute; jobs that worked are in the map by then and skipped. After
// 5 failed minutes that event is given up, so one bad event can't hold up the rest for ever.
let next = typeof r.cursor === 'number' ? r.cursor : Number(store.cursor ?? 0);
if (first !== null) {
  const tries = store.retry?.seq === first ? store.retry.tries + 1 : 1;
  store.retry = { seq: first, tries };
  if (tries <= 5) next = first - 1;
}
if (next > Number(store.cursor ?? 0)) store.cursor = next;
return jobs.map((json) => ({ json, pairedItem: { item: 0 } }));

// Remember the epic before telling NextUp: if the write-back fails, the next run still knows the
// project has its epic and never makes a second one. Whole objects are assigned back, so n8n
// notices the change and saves it.
const store = $getWorkflowStaticData('global');
const s = $('Settings').first().json;
const projects = { ...(store.projects ?? {}) };
const issues = { ...(store.issues ?? {}) };
const out = $input.all().map((it, i) => {
  const job = $('Epic or issue?').itemMatching(i).json;
  const key = it.json.key;
  const url = s.jiraBase + '/browse/' + key;
  projects[job.projectId] = { key, url };
  issues[key] = { projectId: job.projectId, stepId: null };
  return { json: { slug: job.slug, apiBase: job.apiBase, projectId: job.projectId, key, url }, pairedItem: { item: i } };
});
store.projects = projects;
store.issues = issues;
return out;

// A step's issue goes under its project's epic. A project with no epic here (opened before this
// workflow was active, or its epic could not be created) gets no issues: add those in Jira by hand.
const store = $getWorkflowStaticData('global');
const projects = store.projects ?? {};
const steps = store.steps ?? {};
const out = [];
$input.all().forEach((it, i) => {
  const epic = projects[it.json.projectId];
  if (epic && !steps[it.json.stepId]) out.push({ json: { ...it.json, epic: epic.key }, pairedItem: { item: i } });
});
return out;

// Remember issue <-> step before telling NextUp, as for the epic.
const store = $getWorkflowStaticData('global');
const s = $('Settings').first().json;
const steps = { ...(store.steps ?? {}) };
const issues = { ...(store.issues ?? {}) };
const out = $input.all().map((it, i) => {
  const step = $('Find the epic').itemMatching(i).json;
  const key = it.json.key;
  steps[step.stepId] = key;
  issues[key] = { projectId: step.projectId, stepId: step.stepId };
  return {
    json: { slug: step.slug, apiBase: step.apiBase, projectId: step.projectId, stepId: step.stepId, key, url: s.jiraBase + '/browse/' + key },
    pairedItem: { item: i },
  };
});
store.steps = steps;
store.issues = issues;
return out;

// What the Jira automation rule sent (docs/INTEGRATIONS.md, "Jira through n8n"): the issue key,
// and for a comment its id and text. The status is not taken from here: the next node reads it
// from Jira itself. Issues this workflow didn't create are ignored. This side only READS static
// data, so a webhook run can never overwrite what a poll run has just remembered.
const s = $('Settings').first().json;
const store = $getWorkflowStaticData('global');
const issues = store.issues ?? {};

// A comment body is text, or Atlassian Document Format (REST v3): keep the words.
function plain(node) {
  if (typeof node === 'string') return node;
  if (!node || typeof node !== 'object') return '';
  const inner = Array.isArray(node.content) ? node.content.map(plain).join(node.type === 'doc' ? '\n' : '') : '';
  return (typeof node.text === 'string' ? node.text : '') + inner;
}

const out = [];
$input.all().forEach((it, i) => {
  const b = it.json.body ?? {};
  const key = String(b.issue?.key ?? '').trim();
  const link = issues[key];
  if (!link) return;
  const base = { slug: s.slug, apiBase: s.apiBase, jiraBase: s.jiraBase, key, projectId: link.projectId };
  if (b.comment) {
    const text = plain(b.comment.body).trim();
    if (!text) return;
    out.push({ json: { ...base, kind: 'comment', commentId: String(b.comment.id ?? ''), text: ('Jira ' + key + ': ' + text).slice(0, 4000) }, pairedItem: { item: i } });
  } else if (link.stepId) {
    out.push({ json: { ...base, kind: 'status', stepId: link.stepId }, pairedItem: { item: i } });
  }
});
return out;

// Jira's status CATEGORY decides, not the status name, so renamed or extra columns still work:
// Done -> done, In Progress -> doing, To Do -> todo (a reopened issue). A move inside one category
// (In Progress -> In Review) keeps statuscategorychangedate, so the idempotency key repeats and
// NextUp records no second move. Epics never get here: they have no step.
const TO = { done: 'done', indeterminate: 'doing', new: 'todo' };
const out = [];
$input.all().forEach((it, i) => {
  const call = $('Read the Jira call').itemMatching(i).json;
  const f = it.json.fields ?? {};
  const to = TO[f.status?.statusCategory?.key];
  if (!to) return;
  const since = f.statuscategorychangedate ?? f.updated ?? String(Date.now());
  out.push({ json: { ...call, to, idem: ('jira:' + call.key + ':' + to + ':' + since).slice(0, 200) }, pairedItem: { item: i } });
});
return out;
